//
// Units: a price of P USD per million tokens equals P microdollars per token, so cost_micro = ceil(tokens · P + …).
import { z } from 'npm:zod@3.23.8';
import pricesJson from '../../../config/prices.json' with { type: 'json' };

const usd = z.number().finite().nonnegative().nullable();

export const PriceEntrySchema = z
  .object({
    provider: z.string().min(1).max(32),
    model: z.string().min(1).max(64),
    arm: z.enum(['llm-list', 'jev-point', 'any']),
    billing: z.enum(['tokens', 'tokens+units']),
    inputUsdPerMTok: usd,
    outputUsdPerMTok: usd,
    perCallUsd: usd,
    /** Per billed unit (e.g. one Jev question); units = number of questions for jev-point, 0 for llm-list. */
    perUnitUsd: usd,
    /** Documented per-request overhead added to the UTF-8 byte count (× max(1, units)); placeholder until verified. */
    perRequestOverheadTokens: z.number().int().nonnegative().max(100_000),
    priceVerified: z.boolean(),
    boundVerified: z.boolean(),
    source: z.string().nullable(),
    note: z.string(),
  })
  .strict();

export const PriceTableSchema = z
  .object({
    schemaVersion: z.literal(1),
    datedAt: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'datedAt must be YYYY-MM-DD'),
    currency: z.literal('USD'),
    note: z.string(),
    entries: z.array(PriceEntrySchema).min(1),
  })
  .strict()
  .superRefine((t, ctx) => {
    const seen = new Set<string>();
    for (const e of t.entries) {
      const k = `${e.provider}/${e.model}`;
      if (seen.has(k)) ctx.addIssue({ code: z.ZodIssueCode.custom, message: `duplicate price entry ${k}` });
      seen.add(k);
    }
  });

export type PriceEntry = z.infer<typeof PriceEntrySchema>;
export type PriceTable = z.infer<typeof PriceTableSchema>;

export function parsePriceTable(json: unknown): PriceTable {
  const r = PriceTableSchema.safeParse(json);
  if (!r.success) throw new Error(`prices.json: ${r.error.issues[0].path.join('.')}: ${r.error.issues[0].message}`);
  return r.data;
}

/** The repository price table, validated at module load. */
export const PRICE_TABLE: PriceTable = parsePriceTable(pricesJson);

/** Exact (provider, model) lookup: no alias substitution (PLAN §7 step 5). */
export function priceFor(table: PriceTable, provider: string, model: string): PriceEntry | null {
  return table.entries.find((e) => e.provider === provider && e.model === model) ?? null;
}

/** A price entry whose every price field is known. */
export interface CompletePrice {
  provider: string;
  model: string;
  inputUsdPerMTok: number;
  outputUsdPerMTok: number;
  perCallUsd: number;
  perUnitUsd: number;
  perRequestOverheadTokens: number;
  priceTableDate: string;
}

export type PriceCheck = { ok: true; price: CompletePrice } | { ok: false; code: 'price_missing'; detail: string };

export function completePrice(table: PriceTable, entry: PriceEntry | null): PriceCheck {
  if (!entry) return { ok: false, code: 'price_missing', detail: 'no price entry for this provider/model' };
  const { inputUsdPerMTok, outputUsdPerMTok, perCallUsd, perUnitUsd } = entry;
  if (inputUsdPerMTok === null || outputUsdPerMTok === null || perCallUsd === null || perUnitUsd === null) {
    const missing = (['inputUsdPerMTok', 'outputUsdPerMTok', 'perCallUsd', 'perUnitUsd'] as const).filter((k) => entry[k] === null);
    return { ok: false, code: 'price_missing', detail: `${entry.provider}/${entry.model}: ${missing.join(', ')} unknown` };
  }
  return {
    ok: true,
    price: {
      provider: entry.provider,
      model: entry.model,
      inputUsdPerMTok,
      outputUsdPerMTok,
      perCallUsd,
      perUnitUsd,
      perRequestOverheadTokens: entry.perRequestOverheadTokens,
      priceTableDate: table.datedAt,
    },
  };
}

export type LiveGate = { ok: true; price: CompletePrice } | { ok: false; code: 'price_missing' | 'bound_unverified'; detail: string };

/** Live adapters need a complete price AND boundVerified: true; otherwise price_missing (500) / bound_unverified (503). */
export function liveGate(table: PriceTable, provider: string, model: string): LiveGate {
  const entry = priceFor(table, provider, model);
  const c = completePrice(table, entry);
  if (!c.ok) return c;
  if (!entry?.boundVerified) return { ok: false, code: 'bound_unverified', detail: `${provider}/${model}: boundVerified is false` };
  return c;
}
